<div class="page-actions"><div><p class="mb-0"><?= $fieldMode?'Pekerjaan yang ditugaskan kepada Anda.':'Kelola seluruh Job Order, assignment, schedule, field work, costing, dan completion.' ?></p></div><?php if(!$fieldMode && \App\Core\Auth::can('job.create')): ?><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#jobModal"><i class="bi bi-plus-lg"></i> New Job</button><?php endif; ?></div>
<?php if($fieldMode): ?><div class="mobile-job-grid"><?php foreach($jobs as $j): ?><a class="mobile-job-card" href="<?= url('/jobs/'.$j['id']) ?>"><div class="d-flex justify-content-between"><strong><?= e($j['job_number']) ?></strong><span class="status-badge"><?= e($j['status']) ?></span></div><h3><?= e($j['customer_name']) ?></h3><p><?= e(mb_strimwidth($j['description'],0,90,'…')) ?></p><div class="job-meta"><span><i class="bi bi-calendar3"></i> <?= e($j['scheduled_date']?:'Not scheduled') ?></span><span><i class="bi bi-exclamation-circle"></i> <?= e($j['priority']) ?></span></div></a><?php endforeach; ?></div><?php else: ?>
<div class="card-panel"><div class="table-responsive"><table class="table align-middle datatable"><thead><tr><th>Job</th><th>Customer</th><th>Schedule</th><th>Technician</th><th>Priority</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($jobs as $j): ?><tr><td><a href="<?= url('/jobs/'.$j['id']) ?>"><strong><?= e($j['job_number']) ?></strong></a><small class="d-block text-secondary"><?= e(mb_strimwidth($j['description'],0,55,'…')) ?></small></td><td><?= e($j['customer_name']) ?></td><td><?= e($j['scheduled_date']?:'-') ?></td><td><?= e($j['technicians']?:'Unassigned') ?></td><td><?= e($j['priority']) ?></td><td><span class="status-badge"><?= e($j['status']) ?></span></td><td class="text-end"><a class="btn btn-sm btn-light" href="<?= url('/jobs/'.$j['id']) ?>"><i class="bi bi-arrow-right"></i></a></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
<?php if(!$fieldMode): ?><div class="modal fade" id="jobModal"><div class="modal-dialog modal-lg"><form class="modal-content ajax-form" method="post" action="<?= url('/jobs') ?>"><?= csrf_field() ?><div class="modal-header"><h5>New Job Order</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body row g-3"><div class="col-md-6"><label class="form-label">Customer</label><select class="form-select" name="customer_id" required><option value="">Select</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Category</label><input class="form-control" name="service_category"></div><div class="col-md-4"><label class="form-label">Priority</label><select class="form-select" name="priority"><?php foreach(['Low','Normal','High','Urgent','Emergency'] as $p): ?><option <?= $p==='Normal'?'selected':'' ?>><?= e($p) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Schedule</label><input class="form-control" type="datetime-local" name="scheduled_date"></div><div class="col-md-4"><label class="form-label">Estimated Duration (min)</label><input class="form-control" type="number" name="estimated_duration"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" rows="4" name="description" required></textarea></div></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Create Job</button></div></form></div></div><?php endif; ?>
